{id:連番(latest内max+1), name, part:PARTS値, stage:STG段階ラベル文字列(表示用メタのみ), cats:[RCATS], exercises:[{name, cat, sets:number|null, reps:number|null, duration:number|null, videoUrl, note}], createdBy, createdAt:'YYYY-MM-DD'}
